const { chromium } = require('@playwright/test')
const BASE = 'http://127.0.0.1:8095/'
const OUT = 'D:/repository/苏住房防汛C端/artifacts'
const EXE = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'

;(async () => {
  const browser = await chromium.launch({ executablePath: EXE })

  // 1) No token -> should land on login page
  let ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
  let page = await ctx.newPage()
  await page.goto(BASE, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(2500)
  await page.screenshot({ path: `${OUT}/flow-no-token.png`, timeout: 60000 })
  console.log('no-token url:', page.url())
  await ctx.close()

  // 2) With token in storage -> should land on systems page
  ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
  page = await ctx.newPage()
  await page.goto(BASE, { waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.evaluate(() => { window.localStorage.setItem('flood-token-v1', 'fake-token-for-test') })
  await page.reload({ waitUntil: 'domcontentloaded', timeout: 60000 })
  await page.waitForTimeout(2500)
  await page.screenshot({ path: `${OUT}/flow-with-token.png`, timeout: 60000 })
  console.log('with-token url:', page.url())
  await ctx.close()

  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

